/**
 * The last transition written to the row. `pending_payment` means a chargeable plan was selected and the signed webhook has not yet confirmed payment. Note this is the STORED status — a row may read `active` while its period has already elapsed; see `lapsed`.
 */
export type SubscriptionStatus = typeof SubscriptionStatus[keyof typeof SubscriptionStatus];


export const SubscriptionStatus = {
  trialing: 'trialing',
  pending_payment: 'pending_payment',
  active: 'active',
  past_due: 'past_due',
  cancelled: 'cancelled',
} as const;

export interface Subscription {
  workspaceId: number;
  plan: SubscriptionPlan;
  billingPeriod: SubscriptionBillingPeriod;
  /** The last transition written to the row. `pending_payment` means a chargeable plan was selected and the signed webhook has not yet confirmed payment. Note this is the STORED status — a row may read `active` while its period has already elapsed; see `lapsed`. */
  status: SubscriptionStatus;
  paidMonths?: number;
  freeMonths?: number;
  amountMinor?: number;
  currency: string;
  /** @nullable */
  startedAt?: string | null;
  /** @nullable */
  currentPeriodEnd?: string | null;
  /** Whether the period has elapsed, derived server-side on every read. Never computed in the browser: the browser's clock is not what enforcement uses, and the two disagreeing would show a chamber a plan the server has already stopped honouring. */
  lapsed?: boolean;
  /**
     * Whole days until `currentPeriodEnd`, server-computed. Null when no period is running, negative once it has elapsed.
     * @nullable
     */
  daysLeft?: number | null;
  /** This chamber has never had a plan in force. Distinct from `lapsed`, which means one WAS in force and ran out — "your plan expired" is a bewildering thing to read on the day you signed up. Enforcement uses the same flag, so a client that gates on it shows the subscription screen exactly when the API would answer 402 `payment_required`. Derived, never stored: `status` may read `trialing` on a chamber that abandoned a checkout, and `startedAt` is the honest test. */
  neverPaid?: boolean;
  /** @nullable */
  updatedBy?: string | null;
}

